/* Strict display rule override safeguard */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #2b213a;
  --card-bg: #fffbf0;
  --card-border: #4a3e63;
  --primary: #593b76;
  --primary-hover: #724c96;
  --accent: #2e8b57;
  --accent-hover: #246d44;
  --accent-active: #1a4e31;
  --text-dark: #231b2d;
  --text-muted: #5e546e;
  --badge-bg: #ece5d8;
  --focus-ring: #ff9f1c;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  background-image:
    radial-gradient(#3c2f52 15%, transparent 16%),
    radial-gradient(#3c2f52 15%, transparent 16%);
  background-size: 24px 24px;
  background-position: 0 0, 12px 12px;
  color: var(--text-dark);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 24px 16px;
}

.shelter-card {
  background-color: var(--card-bg);
  border: 4px solid var(--card-border);
  box-shadow: 8px 8px 0px rgba(0, 0, 0, 0.45);
  border-radius: 12px;
  width: 100%;
  max-width: 860px;
  padding: 24px;
}

.shelter-header {
  text-align: center;
  margin-bottom: 24px;
  border-bottom: 2px dashed var(--card-border);
  padding-bottom: 20px;
}

.title {
  font-size: 1.85rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 6px;
  letter-spacing: -0.5px;
}

.subtitle {
  color: var(--text-muted);
  font-size: 1rem;
  margin-bottom: 16px;
}

.counter-bar {
  display: flex;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.counter-badge {
  background: var(--badge-bg);
  border: 2px solid var(--card-border);
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 1rem;
  display: flex;
  align-items: center;
  gap: 8px;
}

.counter-value {
  font-size: 1.25rem;
  color: var(--primary);
}

.filter-container {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 28px;
}

.filter-title {
  font-weight: 600;
  color: var(--text-dark);
}

.filter-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  border: 2px solid var(--card-border);
  border-radius: 6px;
  transition: background-color 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}

button:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.filter-btn {
  background: #ffffff;
  color: var(--primary);
  padding: 6px 14px;
  box-shadow: 2px 2px 0px var(--card-border);
}

.filter-btn:hover {
  background: #f0e8f8;
}

.filter-btn.active {
  background: var(--primary);
  color: #ffffff;
  box-shadow: inset 1px 1px 3px rgba(0, 0, 0, 0.4);
  transform: translateY(1px);
}

.filter-btn:active {
  transform: translateY(2px);
  box-shadow: none;
}

.pet-section {
  margin-bottom: 32px;
}

.section-title {
  font-size: 1.35rem;
  color: var(--primary);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.pet-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 20px;
}

.pet-card {
  background: #ffffff;
  border: 2px solid var(--card-border);
  border-radius: 8px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  box-shadow: 3px 3px 0px rgba(74, 62, 99, 0.25);
}

.pet-canvas {
  image-rendering: pixelated;
  background: #fdf6e2;
  border: 2px solid var(--card-border);
  border-radius: 6px;
  margin-bottom: 12px;
}

.pet-name {
  font-size: 1.2rem;
  color: var(--text-dark);
  margin-bottom: 4px;
}

.pet-meta {
  color: var(--text-muted);
  font-size: 0.95rem;
  margin-bottom: 14px;
}

.adopt-btn {
  width: 100%;
  padding: 8px 16px;
  background-color: var(--accent);
  color: #ffffff;
  box-shadow: 2px 2px 0px var(--card-border);
  margin-top: auto;
}

.adopt-btn:hover {
  background-color: var(--accent-hover);
}

.adopt-btn:active {
  background-color: var(--accent-active);
  transform: translateY(2px);
  box-shadow: none;
}

.adopted-section {
  border-top: 2px dashed var(--card-border);
  padding-top: 24px;
  margin-bottom: 0;
}

.adopted-card {
  opacity: 0.9;
  background: #f7f9f7;
  border-color: #8fa38f;
}

.adopted-badge {
  display: inline-block;
  background: #e1f2e1;
  color: var(--accent);
  font-size: 0.85rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 4px;
  border: 1px solid var(--accent);
  margin-top: auto;
}

.empty-msg {
  text-align: center;
  color: var(--text-muted);
  font-style: italic;
  padding: 20px;
  background: rgba(255, 255, 255, 0.5);
  border-radius: 6px;
}

@media (max-width: 480px) {
  .shelter-card {
    padding: 16px;
  }
  .pet-grid {
    grid-template-columns: 1fr;
  }
  .title {
    font-size: 1.5rem;
  }
}

