      adopted: false,
      palette: { "_": null, "O": "#3e2723", "B": "#a1887f", "D": "#6d4c41", "P": "#ffcdd2", "E": "#1b1b1b" },
      grid: [
        "___OPP____OPP___",
        "___ODP____ODP___",
        "___OBP____OBP___",
        "___OBP____OBP___",
        "___OBP____OBP___",
        "__OBBBPOOPBBBO__",
        "__OBEBBBBBEBBO__",
        "__OBEEBBBEEBBO__",
        "__OBBBPDPBBBBO__",
        "___OBBBBBBBBO___",
        "___OBBBDPBBBO___",
        "__OBBBBDPBBBBO__",
        "__OBBBBBBBBBBO__",
        "__OBPOBBBBOPBO__",
        "__OOOOOOOOOOOO__",
        "________________"
      ]
    }
  ];

  let activeFilter = "all";

  // Elements
  const availableList = document.getElementById("available-list");
  const adoptedList = document.getElementById("adopted-list");
  const availableCountEl = document.getElementById("available-count");
  const adoptedCountEl = document.getElementById("adopted-count");
  const adoptedSectionCountEl = document.getElementById("adopted-section-count");
  const noPetsMsg = document.getElementById("no-pets-msg");
  const noAdoptedMsg = document.getElementById("no-adopted-msg");
  const filterButtons = document.querySelectorAll(".filter-btn");

  // Render pixel art onto canvas
  function renderPixelCanvas(canvas, pet) {
    const ctx = canvas.getContext("2d");
    const pixelSize = 5;
    canvas.width = 16 * pixelSize;
    canvas.height = 16 * pixelSize;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    pet.grid.forEach((row, y) => {
      for (let x = 0; x < row.length; x++) {
        const char = row[x];
        const color = pet.palette[char];
        if (color) {
          ctx.fillStyle = color;
          ctx.fillRect(x * pixelSize, y * pixelSize, pixelSize, pixelSize);
        }
      }
    });
  }

  // Update stats counters
  function updateCounts() {
    const availableCount = PETS.filter(p => !p.adopted).length;
    const adoptedCount = PETS.filter(p => p.adopted).length;

    availableCountEl.textContent = availableCount;
    adoptedCountEl.textContent = adoptedCount;
    adoptedSectionCountEl.textContent = adoptedCount;
  }

  // Render all lists
  function render() {
    availableList.innerHTML = "";
    adoptedList.innerHTML = "";

    const availablePets = PETS.filter(p => !p.adopted);
    const adoptedPets = PETS.filter(p => p.adopted);

    const filteredAvailable = availablePets.filter(p => {
      return activeFilter === "all" || p.species.toLowerCase() === activeFilter.toLowerCase();
    });

    // Render Available Pets
    if (filteredAvailable.length === 0) {
      noPetsMsg.hidden = false;
    } else {
      noPetsMsg.hidden = true;
      filteredAvailable.forEach(pet => {
        const card = document.createElement("article");
        card.className = "pet-card";
        card.setAttribute("aria-label", `${pet.name}, ${pet.species}, ${pet.age}`);

        const canvas = document.createElement("canvas");
        canvas.className = "pet-canvas";
        canvas.setAttribute("aria-hidden", "true");
        renderPixelCanvas(canvas, pet);

        const name = document.createElement("h3");
        name.className = "pet-name";
        name.textContent = pet.name;

        const meta = document.createElement("p");
        meta.className = "pet-meta";
        meta.textContent = `${pet.species} • ${pet.age}`;

        const adoptBtn = document.createElement("button");
        adoptBtn.type = "button";
        adoptBtn.className = "adopt-btn";
        adoptBtn.textContent = `Adopt ${pet.name}`;
        adoptBtn.setAttribute("aria-label", `Adopt ${pet.name} the ${pet.species}`);

        adoptBtn.addEventListener("click", () => {
          adoptPet(pet.id);
        });

        card.appendChild(canvas);
        card.appendChild(name);
        card.appendChild(meta);
        card.appendChild(adoptBtn);
        availableList.appendChild(card);
      });
    }

    // Render Adopted Pets
    if (adoptedPets.length === 0) {
      noAdoptedMsg.hidden = false;
    } else {
      noAdoptedMsg.hidden = true;
      adoptedPets.forEach(pet => {
        const card = document.createElement("article");
        card.className = "pet-card adopted-card";
        card.setAttribute("aria-label", `${pet.name}, Adopted`);

        const canvas = document.createElement("canvas");
        canvas.className = "pet-canvas";
        canvas.setAttribute("aria-hidden", "true");
        renderPixelCanvas(canvas, pet);

        const name = document.createElement("h3");
        name.className = "pet-name";
        name.textContent = pet.name;

        const meta = document.createElement("p");
        meta.className = "pet-meta";
        meta.textContent = `${pet.species} • ${pet.age}`;

        const statusBadge = document.createElement("span");
        statusBadge.className = "adopted-badge";
        statusBadge.textContent = "✓ Adopted";

        card.appendChild(canvas);
        card.appendChild(name);
        card.appendChild(meta);
        card.appendChild(statusBadge);
        adoptedList.appendChild(card);
      });
    }

    updateCounts();
  }

  function adoptPet(petId) {
    const targetPet = PETS.find(p => p.id === petId);
    if (targetPet) {
      targetPet.adopted = true;
      render();
    }
  }

  // Filter button handlers using addEventListener
  filterButtons.forEach(btn => {
    btn.addEventListener("click", () => {
      filterButtons.forEach(b => {
        b.classList.remove("active");
        b.setAttribute("aria-pressed", "false");
      });

      btn.classList.add("active");
      btn.setAttribute("aria-pressed", "true");
      activeFilter = btn.dataset.species;
      render();
    });
  });

  // Initial render
  render();
});
